<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../config/koneksi.php'; require_once __DIR__ . '/../includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('dokumentasi.php'); validate_csrf(); $judul=trim($_POST['judul']??''); $tanggal=trim($_POST['tanggal']??''); $deskripsi=trim($_POST['deskripsi']??''); if($judul===''||$tanggal==='') die('Judul dan tanggal wajib diisi.'); try{ $gambar=upload_image($_FILES['gambar']??null,'../uploads/'); if(!$gambar) die('Gambar wajib diupload.'); db_query($conn,'INSERT INTO dokumentasi (judul,tanggal,deskripsi,gambar) VALUES (?,?,?,?)',[$judul,$tanggal,$deskripsi,$gambar]); redirect('dokumentasi.php'); } catch(Exception $e){ die('Gagal upload dokumentasi: '.e($e->getMessage())); }
